CANONICAL_FRS = [{'id': 'FR-AUTH-01', 'name': 'Đăng ký tài khoản người dùng mới', 'actor': 'Khách vãng lai / Người dùng mới', 'description': 'Cho phép người dùng tạo tài khoản mới với email duy nhất, số điện thoại hợp lệ và mật khẩu mã hóa BCrypt.', 'preconditions': 'Email và số điện thoại chưa tồn tại trong bảng users.', 'expected': 'Tạo bản ghi User mới với role CO_OWNER (mặc định), mã hóa mật khẩu, trả về thông tin đăng ký.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'AuthController.java:register(), AuthService.java:register()'}, {'id': 'FR-AUTH-02', 'name': 'Đăng nhập và cấp phát cặp Token JWT', 'actor': 'Người dùng hệ thống', 'description': 'Xác thực danh tính người dùng bằng email và mật khẩu, cấp phát Access Token (15 phút) và Refresh Token (7 ngày).', 'preconditions': 'Tài khoản tồn tại, mật khẩu trùng khớp và trạng thái hoạt động ACTIVE.', 'expected': 'Trả về HTTP 200 kèm JWT Access Token, Refresh Token, thông tin quyền hạn và hồ sơ người dùng.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'AuthController.java:login(), JwtService.java:generateToken()'}, {'id': 'FR-AUTH-03', 'name': 'Làm mới Access Token thông qua Refresh Token', 'actor': 'Người dùng đã đăng nhập', 'description': 'Cấp mới Access Token khi token cũ hết hạn mà không bắt buộc người dùng phải đăng nhập lại thủ công.', 'preconditions': 'Refresh Token còn hiệu lực, chưa bị thu hồi (revoked = false) và khớp chữ ký HMAC-SHA256.', 'expected': 'Cấp Access Token mới với thời hạn 15 phút, cập nhật thời điểm sử dụng gần nhất của Refresh Token.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'AuthController.java:refreshToken(), RefreshTokenRepository.java'}, {'id': 'FR-AUTH-04', 'name': 'Đăng xuất tài khoản và vô hiệu hóa Token', 'actor': 'Người dùng đang đăng nhập', 'description': 'Thu hồi Refresh Token và xóa phiên đăng nhập hiện thời khỏi bộ lưu trữ trình duyệt máy khách.', 'preconditions': 'Yêu cầu mang Bearer Token hợp lệ.', 'expected': 'Cập nhật Refresh Token thành revoked = true, xóa token tại máy khách, chuyển về trang đăng nhập.', 'priority': 'Cao (Medium)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'AuthController.java:logout(), SecurityConfig.java'}, {'id': 'FR-AUTH-05', 'name': 'Truy vấn hồ sơ cá nhân và quyền hạn người dùng', 'actor': 'Người dùng đang đăng nhập', 'description': 'Truy xuất thông tin chi tiết về tài khoản, danh sách vai trò (Roles) và quyền hạn (Authorities) từ Security Context.', 'preconditions': 'Bearer Token hợp lệ trong Header Authorization.', 'expected': 'Trả về DTO hồ sơ gồm ID, email, fullName, phoneNumber, role, activeStatus.', 'priority': 'Cao (Medium)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'AuthController.java:getMe(), UserPrincipal.java'}, {'id': 'FR-AUTH-06', 'name': 'Cập nhật thông tin cá nhân và đổi mật khẩu', 'actor': 'Người dùng đang đăng nhập', 'description': 'Cho phép người dùng cập nhật họ tên, số điện thoại và thay đổi mật khẩu đăng nhập với mật khẩu cũ hợp lệ.', 'preconditions': 'Mật khẩu cũ khớp bản ghi trong CSDL, mật khẩu mới thỏa mãn độ phức tạp bảo mật.', 'expected': 'Cập nhật mật khẩu mới mã hóa BCrypt, ghi nhật ký kiểm toán và thông báo thành công.', 'priority': 'Trung bình (Medium)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'AuthController.java:changePassword(), PasswordEncoderConfig.java'}, {'id': 'FR-3D-01', 'name': 'Hiển thị và tương tác mô hình xe điện 3D Digital Twin', 'actor': 'Đồng sở hữu, Nhân viên, Quản trị viên', 'description': 'Kết xuất không gian Garage ảo 3D và mô hình xe điện chi tiết bằng Three.js / React Three Fiber với khả năng xoay, thu phóng và lia camera.', 'preconditions': 'Trình duyệt hỗ trợ WebGL 2.0, tệp mô hình GLTF/GLB được tải thành công vào bộ nhớ GPU.', 'expected': 'Canvas 3D hiển thị tương tác mượt mà theo cấu hình phần cứng thiết bị, OrbitControls phản hồi tức thì với thao tác chuột và cảm ứng.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VehicleDigitalTwin.tsx, GarageScene.tsx, OrbitControls'}, {'id': 'FR-3D-02', 'name': 'Tương tác chọn linh kiện xe điện qua Three.js Raycaster', 'actor': 'Người dùng giao diện 3D', 'description': 'Sử dụng kỹ thuật Raycasting để bắt tọa độ va chạm chuột lên các Mesh linh kiện (lốp xe, đèn pha, cửa xe, gương chiếu hậu).', 'preconditions': 'Mô hình xe điện đã được nạp hoàn chỉnh vào Scenegraph.', 'expected': 'Mesh linh kiện được highlight viền sáng (Outline), hiển thị thẻ thông tin Tooltip và cập nhật State quản lý.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VehicleExplorationExperience.tsx, Raycaster, selectVehiclePartWithPoint'}, {'id': 'FR-3D-03', 'name': 'Hiển thị điểm đánh dấu vết trầy xước và tổn hại 3D', 'actor': 'Đồng sở hữu, Nhân viên kiểm định', 'description': 'Gắn các Hotspot tương tác trực tiếp lên tọa độ bề mặt vỏ xe 3D tương ứng với các vết trầy xước hoặc móp méo được ghi nhận.', 'preconditions': 'Danh sách DamageRecordResponse có tọa độ x, y, z tương thích với Mesh xe.', 'expected': 'Các icon cảnh báo màu đỏ/vàng hiển thị đúng vị trí trên thân xe 3D, nhấn vào mở chi tiết biên bản hư hại.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'DamageHotspots.tsx, DamageController.java:getDamagesByVehicle()'}, {'id': 'FR-3D-04', 'name': 'Kích hoạt chế độ X-Ray soi xuyên thấu khối Pin xe điện', 'actor': 'Đồng sở hữu, Nhân viên kỹ thuật', 'description': 'Chuyển đổi vật liệu vỏ xe sang trạng thái trong suốt (opacity = 0.15, transparent = true) và làm nổi bật khối pin đặt dưới gầm xe.', 'preconditions': "Người dùng nhấn nút 'Chế độ X-Ray Pin' hoặc gọi action enterBatteryXrayMode.", 'expected': 'Vỏ xe mờ đi, khối pin phát sáng màu vàng cam hoặc xanh, hiển thị dung lượng SOC và nhiệt độ khối pin.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'worldStore.ts:enterBatteryXrayMode(), BatteryPackMesh.tsx'}, {'id': 'FR-3D-05', 'name': 'Điều khiển trạng thái chuyển động xoay xe (Vehicle Yaw Rotation)', 'actor': 'Người dùng giao diện 3D', 'description': 'Hỗ trợ nút xoay tự động 360 độ và thanh trượt điều chỉnh góc quay thân xe quanh trục thẳng đứng Y (Yaw).', 'preconditions': 'Mesh cha của xe điện tồn tại trong Three.js Scene.', 'expected': 'Góc xoay rotation.y của xe thay đổi mượt mà theo giá trị radian điều khiển, hỗ trợ nút reset về 0 rad.', 'priority': 'Trung bình (Medium)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'worldStore.ts:resetVehicleYaw(), VehicleDigitalTwin.tsx'}, {'id': 'FR-3D-06', 'name': 'Chuyển đổi góc nhìn nhanh Camera Preset (Ngoại thất, Nội thất, Pin)', 'actor': 'Người dùng giao diện 3D', 'description': 'Cho phép chuyển đổi góc nhìn camera tức thì thông qua animation lerp mượt mà tới các vị trí định sẵn.', 'preconditions': 'Camera R3F và OrbitControls đang hoạt động.', 'expected': 'Camera dịch chuyển mượt mà tới tọa độ mục tiêu trong 0.8 giây mà không gây giật lag hình ảnh.', 'priority': 'Trung bình (Medium)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'CameraRig.tsx, cameraPresets.ts'}, {'id': 'FR-3D-07', 'name': 'Khôi phục vị trí mặc định Camera 3D (Camera Reset)', 'actor': 'Người dùng giao diện 3D', 'description': 'Đưa góc nhìn camera và tâm xoay OrbitControls về vị trí chuẩn ban đầu (4.5, 2.2, 4.5) và target (0, 0.75, 0).', 'preconditions': 'Camera đang ở vị trí xoay bất kỳ.', 'expected': 'Zustand triggerCameraReset() kích hoạt, camera trở về góc nhìn mặc định toàn cảnh xe.', 'priority': 'Trung bình (Medium)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'worldStore.ts:triggerCameraReset(), GarageScene.tsx'}, {'id': 'FR-CO-01', 'name': 'Khởi tạo nhóm đồng sở hữu xe điện mới', 'actor': 'Đồng sở hữu sáng lập, Quản trị viên', 'description': 'Tạo nhóm đồng sở hữu mới với tên nhóm, định danh phương tiện và quy chế vận hành ban đầu.', 'preconditions': 'Người tạo có quyền tạo nhóm, phương tiện chưa thuộc nhóm đồng sở hữu nào khác.', 'expected': 'Tạo bản ghi CoOwnershipGroup, gắn người tạo làm nhóm trưởng, cấp hợp đồng cơ sở.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'CoOwnershipController.java:createGroup(), CoOwnershipService.java'}, {'id': 'FR-CO-02', 'name': 'Mời thành viên mới tham gia nhóm đồng sở hữu', 'actor': 'Trưởng nhóm đồng sở hữu, Quản trị viên', 'description': 'Gửi lời mời tham gia nhóm tới email người dùng kèm mã định danh lời mời và tỷ lệ cổ phần đề xuất.', 'preconditions': 'Người mời là thành viên hợp lệ của nhóm, tổng tỷ lệ mời không vượt quá phần nhượng.', 'expected': 'Tạo bản ghi MembershipInvitation, sinh mã kích hoạt duy nhất, gửi thông báo.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'MembershipInvitationController.java:createInvitation()'}, {'id': 'FR-CO-03', 'name': 'Tiếp nhận và ký kết điện tử chấp thuận gia nhập nhóm', 'actor': 'Người dùng được mời', 'description': 'Người dùng mở đường dẫn lời mời, xem dự thảo hợp đồng pháp lý và ký số xác nhận gia nhập nhóm.', 'preconditions': 'Lời mời ở trạng thái PENDING, chưa quá hạn hiệu lực (72 giờ).', 'expected': 'Cập nhật lời mời ACCEPTED, kích hoạt tư cách thành viên, tạo bản ghi OwnershipShare.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'MembershipInvitationController.java:signInvitation()'}, {'id': 'FR-CO-04', 'name': 'Phân chia và quản lý tỷ lệ cổ phần sở hữu xe (Ownership Shares)', 'actor': 'Các đồng sở hữu trong nhóm', 'description': 'Theo dõi tỷ lệ phần trăm sở hữu chính xác của từng thành viên, bảo đảm tổng tỷ lệ luôn bằng 100.0000%.', 'preconditions': 'Nhóm đã hoàn tất phân bổ cổ phần ban đầu.', 'expected': 'Trả về danh sách thành viên kèm tỷ lệ phần trăm sở hữu, quyền biểu quyết tương ứng.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'CoOwnershipController.java:getOwnershipShares(), OwnershipShareRepository.java'}, {'id': 'FR-CO-05', 'name': 'Khởi tạo yêu cầu chuyển nhượng cổ phần nội bộ', 'actor': 'Thành viên chuyển nhượng (Transferor)', 'description': 'Thành viên đề xuất nhượng lại một phần hoặc toàn bộ cổ phần xe cho thành viên khác với giá thỏa thuận.', 'preconditions': 'Bên chuyển nhượng nắm giữ tỷ lệ cổ phần >= tỷ lệ muốn nhượng, không có nợ tồn đọng.', 'expected': 'Tạo bản ghi OwnershipTransferRequest với trạng thái PENDING, gửi thông báo tới bên nhận.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'OwnershipTransferController.java:createTransferRequest()'}, {'id': 'FR-CO-06', 'name': 'Bên nhận xác nhận chấp thuận hoặc từ chối chuyển nhượng', 'actor': 'Bên nhận chuyển nhượng (Transferee)', 'description': 'Bên nhận xem xét giá chuyển nhượng, số cổ phần và xác nhận chấp thuận hoặc bác bỏ yêu cầu.', 'preconditions': 'Yêu cầu chuyển nhượng đang ở trạng thái PENDING.', 'expected': 'Cập nhật yêu cầu sang ACCEPTED (hoặc REJECTED), chuyển tiếp sang bước phê duyệt đồng thuận.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'OwnershipTransferController.java:acceptTransfer()'}, {'id': 'FR-CO-07', 'name': 'Hoàn tất chuyển nhượng và tự động sinh Phụ lục Hợp đồng', 'actor': 'Hệ thống / Quản trị viên', 'description': 'Thực hiện điều chỉnh số dư cổ phần giữa hai bên trong giao dịch ACID và phát hành phiên bản phụ lục hợp đồng mới.', 'preconditions': 'Hai bên đã ký điện tử đồng thuận, thanh toán chuyển nhượng hoàn tất.', 'expected': 'Cổ phần bên chuyển giảm, bên nhận tăng tương ứng, bảo toàn bất biến 100%, sinh CoOwnershipContractVersion.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'OwnershipTransferService.java:completeTransfer(), CoOwnershipContractService.java'}, {'id': 'FR-CO-08', 'name': 'Xử lý yêu cầu rút lui khỏi nhóm đồng sở hữu (Withdrawal Request)', 'actor': 'Thành viên muốn rút lui', 'description': 'Cho phép thành viên gửi nguyện vọng rút lui khỏi nhóm, kích hoạt quy trình chào bán ưu tiên nội bộ cho các thành viên còn lại.', 'preconditions': 'Thành viên đã thanh toán hết các nghĩa vụ chi phí cá nhân tồn đọng.', 'expected': 'Tạo yêu cầu WithdrawalRequest, tự động phân bổ quyền mua ưu tiên theo tỷ lệ cổ phần của các thành viên còn lại.', 'priority': 'Trung bình (Medium)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'OwnershipTransferController.java:createWithdrawalRequest()'}, {'id': 'FR-BOOK-01', 'name': 'Truy vấn lịch biểu sử dụng xe và kiểm tra tính khả dụng', 'actor': 'Đồng sở hữu trong nhóm', 'description': 'Xem trực quan lịch đặt xe theo dạng tuần/tháng, các khung giờ đã được đặt, khung giờ bảo dưỡng và khung giờ trống.', 'preconditions': 'Người dùng thuộc nhóm sở hữu của phương tiện truy vấn.', 'expected': 'Trả về danh sách các khoảng thời gian đã được xác nhận (CONFIRMED) hoặc đang sử dụng (IN_PROGRESS).', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'BookingController.java:getVehicleBookings(), BookingCalendar.tsx'}, {'id': 'FR-BOOK-02', 'name': 'Tạo lịch đặt xe mới với thuật toán chống trùng lấn biên (Boundary Overlap Guard)', 'actor': 'Đồng sở hữu trong nhóm', 'description': 'Tạo lịch sử dụng xe từ thời điểm startTime đến endTime, hệ thống tự động kiểm tra giao thoa thời gian nghiêm ngặt.', 'preconditions': 'Khung giờ đặt không chồng lấn với bất kỳ lịch đặt hoặc bảo dưỡng nào khác, cách thời điểm hiện tại tối thiểu 30 phút.', 'expected': 'Tạo bản ghi Booking mới ở trạng thái CONFIRMED, khóa khung giờ trên lịch biểu nhóm.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'BookingController.java:createBooking(), BookingService.java:checkOverlap()'}, {'id': 'FR-BOOK-03', 'name': 'Gia hạn thời gian sử dụng xe (Booking Extension)', 'actor': 'Đồng sở hữu đang trong phiên đặt', 'description': 'Cho phép người dùng kéo dài thời gian sử dụng thêm nếu khung giờ tiếp theo chưa có người khác đặt xe.', 'preconditions': 'Phiên đặt đang hoạt động, khoảng thời gian gia hạn không xung đột với lịch đặt tiếp theo.', 'expected': 'Cập nhật endTime của phiên đặt xe, phát sinh thông báo xác nhận gia hạn thành công.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'BookingController.java:extendBooking(), TripController.java:checkExtensionAvailability()'}, {'id': 'FR-BOOK-04', 'name': 'Đàm phán nhượng lại khung giờ sử dụng xung đột', 'actor': 'Đồng sở hữu cần gia hạn khẩn cấp', 'description': 'Khi muốn gia hạn nhưng bị trùng với lịch đặt kế tiếp của thành viên khác, hệ thống mở kênh đàm phán trao đổi quyền ưu tiên.', 'preconditions': 'Lịch kế tiếp thuộc về thành viên cùng nhóm đồng sở hữu.', 'expected': 'Gửi yêu cầu TripExtensionNegotiationRequest tới người đặt kế tiếp kèm đề xuất bồi hoàn quyền lợi.', 'priority': 'Trung bình (Medium)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'TripController.java:createNegotiationRequest()'}, {'id': 'FR-BOOK-05', 'name': 'Hủy lịch đặt xe trước giờ khởi hành', 'actor': 'Đồng sở hữu đã tạo lịch đặt', 'description': 'Cho phép hủy lịch đặt xe trước thời điểm khởi hành tối thiểu 60 phút mà không bị trừ hạn ngạch tín nhiệm.', 'preconditions': 'Lịch đặt ở trạng thái CONFIRMED và chưa tới giờ khởi hành.', 'expected': 'Cập nhật trạng thái Booking sang CANCELLED, giải phóng khung giờ trên lịch biểu cho thành viên khác.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'BookingController.java:cancelBooking()'}, {'id': 'FR-BOOK-06', 'name': 'Kiểm tra điều kiện bàn giao xe trước phiên đặt (Handover Eligibility)', 'actor': 'Đồng sở hữu, Nhân viên trực trạm', 'description': 'Kiểm tra tự động tình trạng sẵn sàng của xe: pin >= 20%, không bị khóa bảo dưỡng, không có chuyến đi trước chưa trả.', 'preconditions': 'Lịch đặt chuẩn bị bắt đầu trong vòng 15 phút.', 'expected': 'Trả về HandoverEligibilityResponse với trạng thái ELIGIBLE hoặc danh sách lý do chưa đủ điều kiện.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VehicleHandoverController.java:getHandoverEligibility()'}, {'id': 'FR-BOOK-07', 'name': 'Thực hiện biên bản bàn giao xe kỹ thuật số', 'actor': 'Nhân viên vận hành và Đồng sở hữu', 'description': 'Ghi nhận mức pin ban đầu, số km công tơ mét, ảnh chụp ngoại thất và xác nhận tình trạng sạch sẽ của xe.', 'preconditions': 'Cả nhân viên và người nhận xe đều có mặt xác thực trên ứng dụng.', 'expected': 'Tạo bản ghi VehicleHandover, cập nhật trạng thái xe READY_FOR_TRIP, mở quyền bắt đầu chuyến đi.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VehicleHandoverController.java:createHandover(), VehicleInspectionController.java'}, {'id': 'FR-BOOK-08', 'name': 'Xác nhận nhận xe điện tử hai bên (Dual Owner Confirmation)', 'actor': 'Đồng sở hữu nhận xe', 'description': 'Đồng sở hữu kiểm tra xe thực tế, đối chiếu với biên bản kiểm định số và nhấn nút xác nhận nhận xe trên ứng dụng.', 'preconditions': 'Nhân viên đã hoàn thành biên bản bàn giao bước 1.', 'expected': 'Cập nhật Handover thành COMPLETED, phát sinh sự kiện cấp chìa khóa số ảo (Digital Key).', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VehicleHandoverController.java:confirmOwnerReceipt()'}, {'id': 'FR-CHG-01', 'name': 'Khởi tạo phiên sạc pin tại trạm sạc EVShare', 'actor': 'Đồng sở hữu hoặc Nhân viên vận hành', 'description': 'Cắm súng sạc vào xe, quét mã QR trên trụ sạc để khởi tạo phiên nạp năng lượng mới.', 'preconditions': 'Trụ sạc ở trạng thái AVAILABLE, xe đang kết nối vật lý với súng sạc.', 'expected': 'Tạo bản ghi ChargingSession ở trạng thái CHARGING, ghi nhận mức pin khởi đầu (Start SOC).', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'ChargingSessionController.java:startChargingSession()'}, {'id': 'FR-CHG-02', 'name': 'Giám sát thông số sạc pin thời gian thực qua giao diện 3D', 'actor': 'Đồng sở hữu, Nhân viên', 'description': 'Hiển thị công suất sạc tức thời (kW), điện áp (V), dòng điện (A), thời gian sạc ước tính và biểu đồ nhiệt độ pin.', 'preconditions': 'Phiên sạc đang diễn ra (status = CHARGING).', 'expected': 'Giao diện cập nhật liên tục các chỉ số năng lượng mỗi 5 giây qua REST Polling / WebSocket.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'ChargingSessionController.java:getActiveSession(), ChargingPanel.tsx'}, {'id': 'FR-CHG-03', 'name': 'Hoàn tất phiên sạc và tính toán điện năng tiêu thụ', 'actor': 'Người dùng hoặc Nhân viên kết thúc sạc', 'description': 'Ngắt súng sạc, hệ thống tính tổng điện năng tiêu thụ (kWh), áp dụng hiệu suất nạp 92% và đơn giá điện EVN 3.850 đ/kWh.', 'preconditions': 'Phiên sạc đang hoạt động, súng sạc được rút an toàn.', 'expected': 'Cập nhật ChargingSession thành COMPLETED, ghi nhận năng lượng nạp thực tế vào kho điện xe.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'ChargingSessionController.java:completeChargingSession(), EnergyInventoryService.java'}, {'id': 'FR-CHG-04', 'name': 'Quản lý kho năng lượng xe (Energy Inventory) và giá vốn bình quân gia quyền (WAC)', 'actor': 'Hệ thống quản lý năng lượng', 'description': 'Theo dõi lượng điện tích lũy trong pin xe (kWh) và tính toán lại đơn giá vốn bình quân gia quyền (WAC) mỗi khi nạp mới.', 'preconditions': 'Phát sinh giao dịch nạp điện hoàn tất có ghi nhận sản lượng và chi phí nạp.', 'expected': 'Cập nhật VehicleEnergyInventory: năng lượng tồn, đơn giá WAC mới, ghi nhật ký VehicleEnergyTransaction.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'EnergyInventoryController.java:getEnergyInventory(), VehicleEnergyInventoryService.java'}, {'id': 'FR-CHG-05', 'name': 'Sạc vận hành chuyên trách bởi Nhân viên (Staff Operational Charging)', 'actor': 'Nhân viên vận hành (Staff)', 'description': 'Nhân viên chủ động sạc pin xe khi pin yếu tại bãi xe, chi phí nạp được tính vào quỹ chung hoặc tạm ứng vận hành.', 'preconditions': 'Tài khoản thực hiện có role STAFF hoặc ADMIN.', 'expected': 'Phiên sạc được gắn cờ isOperational = true, không phát sinh nghĩa vụ nợ cá nhân cho nhân viên.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VehicleEnergyInventoryService.java:recordOperationalCharging()'}, {'id': 'FR-CHG-06', 'name': 'Hủy phiên sạc khẩn cấp khi xảy ra lỗi kỹ thuật', 'actor': 'Người dùng, Nhân viên, Hệ thống', 'description': 'Ngắt sạc tức thời khi phát hiện quá nhiệt pin, sụt áp lưới điện hoặc có lệnh dừng khẩn cấp từ người dùng.', 'preconditions': 'Phiên sạc đang hoạt động và nhận tín hiệu cảnh báo an toàn.', 'expected': 'Dừng dòng sạc ngay lập tức, chuyển trạng thái CANCELLED/ERROR, ghi nhận lý do vào nhật ký.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'ChargingSessionController.java:cancelChargingSession()'}, {'id': 'FR-TRIP-01', 'name': 'Bắt đầu chuyến đi (Start Trip) với chốt chặn an toàn Pin', 'actor': 'Đồng sở hữu đang trong phiên đặt', 'description': 'Mở khóa xe và kích hoạt phiên di chuyển, hệ thống kiểm tra bắt buộc mức pin xe phải đạt tối thiểu 20%.', 'preconditions': 'Đã hoàn tất bàn giao xe, trong khung giờ đặt hợp lệ, dung lượng pin >= 20%.', 'expected': 'Tạo bản ghi Trip ở trạng thái IN_PROGRESS, ghi nhận Start Odometer và Start SOC, mở khóa chìa ảo.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'TripController.java:startTrip(), TripService.java:startTrip()'}, {'id': 'FR-TRIP-02', 'name': 'Theo dõi hành trình và tiêu hao năng lượng xe điện tức thời', 'actor': 'Đồng sở hữu, Hệ thống điều hành', 'description': 'Cập nhật quãng đường lăn bánh, lượng pin tiêu thụ theo mô hình động lực học xe điện (kWh/km).', 'preconditions': 'Chuyến đi đang ở trạng thái IN_PROGRESS.', 'expected': 'Cung cấp số liệu tiêu hao năng lượng tức thời và ước tính phạm vi hoạt động còn lại trên màn hình 3D.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VehicleEnergyModelService.java, ActiveTripDetailPanel.tsx'}, {'id': 'FR-TRIP-03', 'name': 'Gửi yêu cầu hoàn trả xe sau khi kết thúc di chuyển', 'actor': 'Đồng sở hữu hoàn thành chuyến đi', 'description': "Đưa xe về vị trí đỗ quy định, nhấn nút 'Yêu cầu trả xe' trên ứng dụng để thông báo cho nhân viên kiểm tra.", 'preconditions': 'Xe đã về vị trí đỗ tại trạm, xe đã tắt máy và đóng kín các cửa.', 'expected': 'Chuyển trạng thái Trip sang PENDING_RETURN, gửi thông báo đẩy tới danh sách nhân viên trực ca.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'TripController.java:requestReturn()'}, {'id': 'FR-TRIP-04', 'name': 'Kiểm tra tiếp nhận và nghiệm thu xe sau chuyến đi', 'actor': 'Nhân viên vận hành', 'description': 'Nhân viên tiến hành kiểm tra xe thực địa, ghi nhận km công tơ mét kết thúc, mức pin kết thúc và chụp ảnh kiểm định.', 'preconditions': 'Chuyến đi đang ở trạng thái PENDING_RETURN.', 'expected': 'Lập biên bản hoàn trả xe số, ghi nhận nếu có phát sinh tổn hại mới so với trước chuyến đi.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VehicleInspectionController.java:completeInspection(), VehicleHandoverController.java'}, {'id': 'FR-TRIP-05', 'name': 'Xác nhận kết thúc chuyến đi và tự động khấu trừ kho năng lượng', 'actor': 'Nhân viên vận hành / Hệ thống', 'description': 'Hoàn tất nghiệm thu chuyến đi, hệ thống tính lượng điện năng tiêu thụ thực tế = Start SOC - End SOC, nhân với đơn giá WAC để tính chi phí điện.', 'preconditions': 'Biên bản hoàn trả xe đã được nhân viên ký duyệt.', 'expected': 'Trip chuyển thành COMPLETED, khấu trừ kho năng lượng xe, sinh hóa đơn chi phí sử dụng năng lượng cá nhân.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'TripController.java:confirmReturn(), VehicleEnergyInventoryService.java:deductEnergy()'}, {'id': 'FR-TRIP-06', 'name': 'Ghi nhận vết tổn hại / trầy xước phát sinh trong chuyến đi', 'actor': 'Nhân viên vận hành, Đồng sở hữu', 'description': 'Nếu phát hiện hư hỏng mới, nhân viên đánh dấu vị trí 3D trên mô hình xe, chụp ảnh bằng chứng và ước tính chi phí khắc phục.', 'preconditions': 'Chuyến đi vừa kết thúc và phát hiện có tổn hại mới so với lúc bàn giao.', 'expected': 'Tạo bản ghi DamageRecord gắn liền với trip_id và vehicle_id, kích hoạt cảnh báo bồi thường.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'DamageController.java:recordTripDamage()'}, {'id': 'FR-EXP-01', 'name': 'Ghi nhận hóa đơn chi phí chung (Bảo dưỡng, Đăng kiểm, Bảo hiểm, Bãi đỗ)', 'actor': 'Đồng sở hữu, Nhân viên phụ trách', 'description': 'Nhập hóa đơn chi phí phát sinh chung của xe kèm loại chi phí, số tiền, ngày phát sinh và ảnh chứng từ hóa đơn đỏ.', 'preconditions': 'Người tạo có quyền trong nhóm hoặc là nhân viên phụ trách xe.', 'expected': 'Tạo bản ghi Expense ở trạng thái PENDING_APPROVAL, lưu trữ chứng từ đính kèm.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'ExpenseController.java:recordExpense()'}, {'id': 'FR-EXP-02', 'name': 'Tự động phân bổ nghĩa vụ chi phí theo tỷ lệ cổ phần sở hữu', 'actor': 'Hệ thống kế toán tự động', 'description': 'Phân bổ số tiền hóa đơn chung cho từng thành viên theo đúng tỷ lệ phần trăm sở hữu xe, áp dụng thuật toán phần dư lớn nhất Hare-Niemeyer để làm tròn tiền tệ chính xác tới từng đồng VND.', 'preconditions': 'Hóa đơn chi phí được phê duyệt hợp lệ.', 'expected': 'Tạo danh sách ExpenseShare cho từng thành viên, tổng số tiền phân bổ khớp 100% hóa đơn gốc.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'ExpenseShareService.java:reconcileExpenseShares(), Hare-Niemeyer rounding'}, {'id': 'FR-EXP-03', 'name': 'Phân bổ chi phí năng lượng sạc theo người lái và chống trùng lặp (Driver Energy Allocation)', 'actor': 'Hệ thống kế toán tự động / Người lái chuyến đi', 'description': 'Tự động kết xuất chi phí điện năng tiêu thụ từ phiên di chuyển theo chính sách USER_RESPONSIBILITY, gán trực tiếp 100% nghĩa vụ nợ cho người lái xe. Thực thi cơ chế lũy đẳng (idempotent), ngăn ngừa tạo trùng lặp hóa đơn chi phí cho cùng một chuyến đi.', 'preconditions': 'Chuyến đi đã hoàn tất nghiệm thu trả xe, có ghi nhận lượng điện năng tiêu thụ thực tế.', 'expected': 'Tạo Expense với allocationPolicy = USER_RESPONSIBILITY, gán responsibleUser = driver. Không sinh trùng lặp bản ghi nếu đã tồn tại.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'ExpenseService.java:createTripEnergyExpense(), ExpenseShareService.java:generateSharesForExpense()'}, {'id': 'FR-EXP-04', 'name': 'Quản lý nghĩa vụ tài chính cá nhân và tra cứu hồ sơ lịch sử (Personal Obligations & History)', 'actor': 'Đồng sở hữu, Kế toán, Quản trị viên', 'description': 'Cung cấp bảng tổng hợp công nợ chi phí cá nhân theo từng thành viên và từng phương tiện. Phân định rõ nợ từ chi phí chung (theo % vốn) và nợ năng lượng chuyến đi (trách nhiệm người lái). Lưu giữ các bản ghi quỹ chung và đóng góp cũ làm hồ sơ lịch sử tham chiếu minh bạch.', 'preconditions': 'Người dùng đã xác thực, có phân quyền truy cập thông tin tài chính của nhóm xe.', 'expected': 'Trả về danh sách nghĩa vụ nợ cá nhân, trạng thái SETTLED/UNPAID và lịch sử hạch toán. Dữ liệu quỹ cũ chỉ hiển thị ở chế độ tham chiếu lịch sử.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'ExpenseShareService.java:getCostSharingSummary(), PersonalPaymentController.java:getPaymentsForCurrentUser(), SharedFundController.java (Legacy/Historical)'}, {'id': 'FR-EXP-05', 'name': 'Thanh toán nghĩa vụ chi phí cá nhân phát sinh (Personal Expense Payment)', 'actor': 'Đồng sở hữu có nợ chi phí', 'description': 'Đồng sở hữu thanh toán nghĩa vụ nợ (tiền sạc điện chuyến đi, tiền bồi thường trầy xước, phần phân bổ chi phí sửa chữa).', 'preconditions': 'Người dùng có bản ghi ExpenseShare ở trạng thái UNPAID.', 'expected': 'Tạo bản ghi PersonalExpensePayment, tải ủy nhiệm chi, chuyển trạng thái PENDING_VERIFICATION.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'PersonalPaymentController.java:submitPayment()'}, {'id': 'FR-EXP-06', 'name': 'Đối soát và xác nhận thanh toán nợ cá nhân', 'actor': 'Nhân viên tài chính / Quản trị viên', 'description': 'Kiểm tra biên lai chuyển khoản ngân hàng thực tế, xác nhận khớp số tiền và gạch nợ cho thành viên.', 'preconditions': 'Tài khoản duyệt không được phép là chính người nợ (ngăn chặn tự phê duyệt nợ của bản thân).', 'expected': 'Cập nhật trạng thái ExpenseShare sang PAID, cập nhật PersonalExpensePayment sang VERIFIED.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'PersonalPaymentController.java:verifyPayment(), PersonalPaymentService.java'}, {'id': 'FR-VOTE-01', 'name': 'Khởi tạo đề xuất biểu quyết chung trong nhóm (Vote Proposal)', 'actor': 'Đồng sở hữu trong nhóm', 'description': 'Tạo đề xuất biểu quyết về các vấn đề trọng đại: nâng cấp phụ kiện, sửa chữa lớn, thay đổi quy chế, kết nạp thành viên mới.', 'preconditions': 'Người tạo là thành viên chính thức của nhóm đồng sở hữu.', 'expected': 'Tạo bản ghi VoteProposal ở trạng thái ACTIVE, xác lập thời hạn bỏ phiếu (thường là 72 giờ).', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VoteProposalController.java:createProposal()'}, {'id': 'FR-VOTE-02', 'name': 'Thực hiện bỏ phiếu biểu quyết với trọng số cổ phần (Equity Weighted Voting)', 'actor': 'Đồng sở hữu hợp lệ', 'description': 'Thành viên bỏ phiếu (Đồng ý, Phản đối, Phiếu trắng) với sức nặng phiếu bầu tỷ lệ thuận chính xác với % cổ phần nắm giữ.', 'preconditions': 'Đề xuất đang mở biểu quyết, thành viên chưa bỏ phiếu cho đề xuất này trước đó.', 'expected': 'Ghi nhận bản ghi ProposalVote kèm trọng số voteWeight = ownershipPercentage, cập nhật tổng điểm tức thời.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VoteProposalController.java:castVote(), VoteProposalService.java:castVote()'}, {'id': 'FR-VOTE-03', 'name': 'Tự động kích hoạt biểu quyết khi chi phí bảo dưỡng vượt ngưỡng', 'actor': 'Hệ thống bảo dưỡng tự động', 'description': 'Khi nhân viên đề xuất báo giá bảo dưỡng vượt hạn mức quy định (ví dụ > 5.000.000 đ), hệ thống tự động khởi tạo đề xuất biểu quyết.', 'preconditions': 'Đợt bảo dưỡng có tổng chi phí dự kiến vượt ngưỡng phê duyệt nhanh.', 'expected': 'Tạo VoteProposal liên kết với maintenance_id, gửi thông báo khẩn tới toàn bộ đồng sở hữu.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VoteProposalController.java:createVoteForMaintenance(), MaintenanceService.java'}, {'id': 'FR-VOTE-04', 'name': 'Theo dõi tiến độ và tỷ lệ biểu quyết thời gian thực', 'actor': 'Đồng sở hữu trong nhóm', 'description': 'Xem trực quan thanh tiến độ biểu quyết: % Đồng ý, % Phản đối, % Chưa bỏ phiếu, thời gian còn lại.', 'preconditions': 'Người dùng thuộc nhóm đồng sở hữu của đề xuất.', 'expected': 'Trả về VoteProposalResponse chứa danh sách phiếu bầu ẩn danh hoặc công khai tùy chính sách.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VoteProposalController.java:getVoteResults()'}, {'id': 'FR-VOTE-05', 'name': 'Tự động chốt kết quả và thực thi nghị quyết (Finalize Proposal)', 'actor': 'Hệ thống lập lịch / Trưởng nhóm', 'description': 'Khi hết hạn biểu quyết hoặc khi tỷ lệ Đồng ý vượt ngưỡng quá bán (ví dụ > 50% hoặc > 66%), hệ thống tự động đóng đề xuất và kích hoạt hành động nghiệp vụ.', 'preconditions': 'Đề xuất đã đủ điều kiện thông qua hoặc hết thời hạn biểu quyết.', 'expected': 'Cập nhật trạng thái PASSED hoặc REJECTED, tự động phê duyệt đợt bảo dưỡng tương ứng nếu PASSED.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VoteProposalController.java:finalizeProposal(), VoteProposalService.java'}, {'id': 'FR-VOTE-06', 'name': 'Cấu hình chính sách biểu quyết nhóm (Voting Policy)', 'actor': 'Trưởng nhóm đồng sở hữu, Quản trị viên', 'description': 'Thiết lập ngưỡng tỷ lệ quá bán (51%, 66%, 75%), thời gian biểu quyết tối thiểu và cơ chế xử lý khi tỷ lệ phiếu hòa.', 'preconditions': 'Người cấu hình có thẩm quyền quản trị nhóm.', 'expected': 'Cập nhật chính sách biểu quyết vào bảng vote_proposals/co_ownership_groups.', 'priority': 'Trung bình (Medium)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'VoteProposalController.java:updateVotingPolicy()'}, {'id': 'FR-DISP-01', 'name': 'Khởi tạo hồ sơ khiếu nại tranh chấp (Create Dispute)', 'actor': 'Đồng sở hữu gặp sự cố / bất đồng', 'description': 'Tạo hồ sơ khiếu nại về các vi phạm: làm trầy xước xe không nhận, trả xe muộn làm lỡ lịch người khác, để xe bẩn, chậm đóng quỹ.', 'preconditions': 'Người tạo là thành viên nhóm hoặc có tham gia phiên đặt xe liên quan.', 'expected': 'Tạo bản ghi Dispute ở trạng thái OPEN, phân loại mức độ ưu tiên, đính kèm chứng từ ban đầu.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'DisputeController.java:createDispute()'}, {'id': 'FR-DISP-02', 'name': 'Tự động phát hiện xung đột lịch đặt và điền trước hồ sơ (Prefill Dispute)', 'actor': 'Hệ thống phát hiện sự cố tự động', 'description': 'Tự động phát hiện trường hợp chuyến đi trước trả muộn xâm lấn vào phiên đặt kế tiếp và tạo sẵn form khiếu nại điền trước số liệu.', 'preconditions': 'Chuyến đi trước kết thúc muộn hơn endTime của booking, gây chậm trễ cho booking kế tiếp.', 'expected': 'Trả về PrefilledDisputeDto chứa sẵn booking_id, vehicle_id, số phút trễ và gợi ý số tiền phạt.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'DisputeController.java:getPrefilledDispute(), BookingIncidentDetectionService.java'}, {'id': 'FR-DISP-03', 'name': 'Phân công nhân viên hòa giải viên chuyên trách (Staff Mediator)', 'actor': 'Quản trị viên hoặc Nhân viên trực ban', 'description': 'Gán một nhân viên vận hành độc lập đóng vai trò người hòa giải trung gian công tâm giữa các bên tranh chấp.', 'preconditions': 'Hồ sơ tranh chấp ở trạng thái OPEN hoặc INVESTIGATING.', 'expected': 'Cập nhật staff_id trong bảng disputes, chuyển trạng thái sang UNDER_MEDIATION.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'DisputeController.java:assignStaffMediator()'}, {'id': 'FR-DISP-04', 'name': 'Nộp bổ sung bằng chứng và tin nhắn hòa giải nội bộ', 'actor': 'Các bên tranh chấp và Hòa giải viên', 'description': 'Gửi tin nhắn trao đổi, ảnh chụp bổ sung, video hành trình và biên bản đối chiếu vào hồ sơ hòa giải tập trung.', 'preconditions': 'Hồ sơ đang trong quá trình hòa giải.', 'expected': 'Tạo bản ghi DisputeMessage và DisputeEvidence, gửi thông báo tức thời tới các bên liên quan.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'DisputeController.java:addMessage(), DisputeController.java:submitEvidence()'}, {'id': 'FR-DISP-05', 'name': 'Đề xuất và biểu quyết phương án bồi thường hòa giải', 'actor': 'Hòa giải viên và các bên liên quan', 'description': 'Hòa giải viên đưa ra kết luận phân định trách nhiệm và số tiền bồi thường; các bên xác nhận chấp thuận hoặc từ chối.', 'preconditions': 'Đã thu thập đầy đủ bằng chứng và kết quả đối soát biên bản xe.', 'expected': 'Ghi nhận DisputeCompensation, nếu các bên chấp thuận thì sinh khoản nợ bồi thường tài chính.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'DisputeController.java:respondToResolution(), DisputeService.java'}, {'id': 'FR-DISP-06', 'name': 'Tất toán bồi thường và đóng hồ sơ tranh chấp (Close Dispute)', 'actor': 'Nhân viên hòa giải / Quản trị viên', 'description': 'Sau khi bên gây thiệt hại hoàn tất thanh toán khoản bồi thường, hồ sơ khiếu nại chính thức được đóng lại.', 'preconditions': 'Khoản bồi thường đã được thanh toán và xác minh đầy đủ.', 'expected': 'Dispute chuyển sang trạng thái RESOLVED / CLOSED, ghi nhật ký kiểm toán toàn diện.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'DisputeController.java:closeDispute(), DisputeCompensationPaymentRepository.java'}, {'id': 'FR-ADM-01', 'name': 'Bảng điều khiển tổng quan số liệu hệ thống (Admin Dashboard)', 'actor': 'Quản trị viên (Admin)', 'description': 'Hiển thị các chỉ số KPI vận hành: tổng số xe điện, số nhóm hoạt động, doanh thu quỹ, tỷ lệ xe sẵn sàng, số phiên sạc.', 'preconditions': 'Tài khoản có quyền ROLE_ADMIN.', 'expected': 'Trả về AdminDashboardStatsResponse gồm đầy đủ biểu đồ và số liệu thời gian thực.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'AdminController.java:getDashboardStats()'}, {'id': 'FR-ADM-02', 'name': 'Quản lý danh sách người dùng và phân quyền tài khoản', 'actor': 'Quản trị viên (Admin)', 'description': 'Xem danh sách người dùng, khóa/mở khóa tài khoản, điều chỉnh vai trò giữa ADMIN, STAFF, CO_OWNER.', 'preconditions': 'Tài khoản người thực hiện là ADMIN.', 'expected': 'Cập nhật role hoặc activeStatus của người dùng, ghi nhật ký kiểm toán hành vi quản trị.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'AdminController.java:updateUserRole(), AdminController.java:updateUserStatus()'}, {'id': 'FR-ADM-03', 'name': 'Tra cứu và giám sát nhật ký kiểm toán an toàn (Audit Logs)', 'actor': 'Quản trị viên an ninh hệ thống', 'description': 'Truy vấn lịch sử toàn bộ các hành vi nhạy cảm: chuyển nhượng cổ phần, gạch nợ chi phí, thay đổi mật khẩu, điều chỉnh cấu hình xe.', 'preconditions': 'Yêu cầu quyền ADMIN.', 'expected': 'Trả về danh sách phân trang bản ghi AuditLog kèm IP, người thực hiện, thời gian, trạng thái trước/sau.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'AdminController.java:getAuditLogs(), AuditLogRepository.java'}, {'id': 'FR-ADM-04', 'name': 'Báo cáo tài chính tổng hợp toàn hệ thống', 'actor': 'Quản trị viên tài chính', 'description': 'Tổng hợp doanh thu sạc điện, tổng chi phí bảo dưỡng phát sinh, tổng số dư quỹ chung và các khoản nợ tồn đọng.', 'preconditions': 'Yêu cầu quyền ADMIN.', 'expected': 'Trả về báo cáo tài chính chi tiết hỗ trợ kết xuất bảng biểu thống kê.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'AdminController.java:getFinancialOverview()'}, {'id': 'FR-ADM-05', 'name': 'Giám sát sức khỏe hạ tầng hệ thống và dịch vụ (Health Check)', 'actor': 'Quản trị viên hệ thống, Kỹ sư DevOps', 'description': 'Kiểm tra trạng thái kết nối CSDL MySQL, dịch vụ lưu trữ hình ảnh và độ trễ phản hồi của hệ thống.', 'preconditions': 'Không yêu cầu xác thực hoặc bảo vệ bằng secret token nội bộ.', 'expected': "Trả về HTTP 200 OK với thông tin trạng thái hoạt động 'UP' của các thành phần dịch vụ.", 'priority': 'Trung bình (Medium)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'HealthController.java:checkHealth()'}, {'id': 'FR-STF-01', 'name': 'Bảng điều hành công việc trực ban của Nhân viên (Staff Dashboard)', 'actor': 'Nhân viên vận hành (Staff)', 'description': 'Theo dõi danh sách các công việc cần xử lý ngay: bàn giao xe sắp khởi hành, tiếp nhận xe hoàn trả, xử lý tranh chấp mới gán.', 'preconditions': 'Tài khoản có quyền ROLE_STAFF hoặc ROLE_ADMIN.', 'expected': 'Hiển thị danh sách công việc ưu tiên kèm thời gian cảnh báo quá hạn.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'StaffOperationalCarousel.tsx, DisputeController.java:getStaffDisputeDashboard()'}, {'id': 'FR-STF-02', 'name': 'Khởi tạo và cập nhật tiến độ bảo dưỡng sửa chữa xe', 'actor': 'Nhân viên kỹ thuật', 'description': 'Lập lệnh bảo dưỡng định kỳ hoặc sửa chữa đột xuất, cập nhật trạng thái từ PENDING sang IN_PROGRESS và COMPLETED.', 'preconditions': 'Xe thuộc danh mục quản lý của trạm trực.', 'expected': 'Cập nhật trạng thái xe thành MAINTENANCE, khóa lịch đặt xe trên ứng dụng trong thời gian bảo dưỡng.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'MaintenanceController.java:createMaintenance(), MaintenanceController.java:startMaintenance()'}, {'id': 'FR-STF-03', 'name': 'Nghiệm thu hoàn tất bảo dưỡng và giải phóng xe về trạng thái sẵn sàng', 'actor': 'Nhân viên kỹ thuật', 'description': 'Kiểm tra chất lượng phụ tùng thay thế, số tiền hóa đơn thực tế và mở khóa xe trở lại trạng thái AVAILABLE.', 'preconditions': 'Công việc bảo dưỡng đã hoàn tất thực tế, xe đạt tiêu chuẩn vận hành an toàn.', 'expected': 'Cập nhật Maintenance thành COMPLETED, cập nhật xe AVAILABLE, kích hoạt phân bổ chi phí hóa đơn.', 'priority': 'Bắt buộc (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'MaintenanceController.java:completeMaintenance(), ExpenseService.java'}, {'id': 'FR-STF-04', 'name': 'Tiếp nhận và nghiệm thu công việc được giao (Staff Approved Work)', 'actor': 'Nhân viên vận hành', 'description': 'Xác nhận nhận việc di chuyển xe giữa các trạm, sạc điện lưu động hoặc kiểm định xe và báo cáo hoàn thành.', 'preconditions': 'Công việc được điều phối viên phân công cho nhân viên.', 'expected': 'Ghi nhận tiến độ công việc, tính phụ cấp vận hành cho nhân viên vào hệ thống.', 'priority': 'Trung bình (Medium)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'StaffApprovedWorkController.java:acceptWork(), StaffApprovedWorkController.java:completeWork()'}, {'id': 'FR-NOTI-01', 'name': 'Thông báo đẩy thời gian thực về biến động lịch xe và tài chính (Real-Time Notification Dispatch)', 'actor': 'Hệ thống điều hành / Người dùng hệ thống', 'description': 'Tự động phát sinh và gửi thông báo thời gian thực tới các thành viên liên quan khi phát sinh sự kiện: có lịch đặt xe mới, yêu cầu đàm phán gia hạn, hóa đơn chi phí phân bổ mới hoặc có đề xuất biểu quyết cần bỏ phiếu.', 'preconditions': 'Sự kiện nghiệp vụ diễn ra thành công (đặt xe, nộp chi phí, tạo biểu quyết).', 'expected': 'Tạo bản ghi Notification cho từng người nhận, cập nhật số lượng thông báo chưa đọc, đẩy tin qua SSE/WebSocket.', 'priority': 'Cao (High)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'NotificationController.java:getNotifications(), NotificationService.java:createNotification()'}, {'id': 'FR-AI-01', 'name': 'Tra cứu quy chế và giải đáp quy trình đồng sở hữu qua Trợ lý ảo AI (AI Assistant Zone)', 'actor': 'Đồng sở hữu, Thành viên mới, Khách vãng lai', 'description': 'Cung cấp giao diện tương tác thông minh với trợ lý AI, hỗ trợ người dùng tra cứu quy chế nhóm, hướng dẫn sử dụng các tính năng 3D, giải đáp chính sách phân bổ chi phí WAC và hướng dẫn giải quyết khiếu nại.', 'preconditions': 'Người dùng mở ô đối thoại AI Assistant hoặc truy cập khu vực AI Zone trong Garage 3D.', 'expected': 'Phản hồi câu trả lời dựa trên tài liệu quy chế được nạp sẵn, gợi ý câu hỏi liên quan, có cơ chế xử lý Timeout an toàn khi mô hình bận.', 'priority': 'Trung bình (Medium)', 'status': 'Hoàn thành đối chiếu mã nguồn', 'source_evidence': 'AiAssistantController.java:chat(), AiAssistantInstallation.tsx, AiService.java'}]

CANONICAL_BRS = [{'id': 'BR-AUTH-01', 'name': 'Quy tắc định dạng và độ phức tạp mật khẩu', 'condition': 'Mật khẩu người dùng phải có độ dài tối thiểu 8 ký tự, bao gồm ít nhất 1 chữ hoa, 1 chữ thường, 1 chữ số và 1 ký tự đặc biệt.', 'module': 'Authentication', 'enforcement': 'Kiểm tra tại tầng DTO Validation (@Pattern) và mã hóa BCrypt với cost factor = 10 trước khi lưu CSDL.', 'source_file': 'AuthService.java, RegisterRequest.java', 'related_ucs': 'UC-AUTH-01, UC-AUTH-02'}, {'id': 'BR-AUTH-02', 'name': 'Quy tắc thời hạn hiệu lực của cặp Token JWT', 'condition': 'Access Token có thời hạn sống tối đa 15 phút (900.000 ms); Refresh Token có thời hạn sống 7 ngày (604.800.000 ms).', 'module': 'Authentication', 'enforcement': "JwtService kiểm tra hạn 'exp' trong claim JWT; Filter chặn HTTP 401 nếu hết hạn.", 'source_file': 'JwtService.java, application.yml', 'related_ucs': 'UC-AUTH-01, UC-AUTH-03'}, {'id': 'BR-AUTH-03', 'name': 'Quy tắc thu hồi hiệu lực Token khi đăng xuất', 'condition': 'Khi người dùng đăng xuất, Refresh Token tương ứng phải bị chuyển cờ revoked = true ngay lập tức để không thể tái sử dụng.', 'module': 'Authentication', 'enforcement': 'Tầng Service cập nhật trạng thái trong bảng refresh_tokens trong cùng một giao dịch ACID.', 'source_file': 'AuthService.java:logout(), RefreshTokenRepository.java', 'related_ucs': 'UC-AUTH-04'}, {'id': 'BR-3D-01', 'name': 'Quy tắc tương thích phần cứng đồ họa WebGL', 'condition': 'Giao diện 3D Digital Twin chỉ khởi tạo khi trình duyệt hỗ trợ WebGL 2.0; nếu không hỗ trợ, tự động hạ cấp xuống giao diện 2D tĩnh.', 'module': '3D Digital Twin', 'enforcement': 'Kiểm tra WebGL Context tại WebGLDetectionGuard trước khi mount R3F Canvas.', 'source_file': 'StandardPanelShell.tsx, GarageScene.tsx', 'related_ucs': 'UC-3D-01, UC-3D-02'}, {'id': 'BR-3D-02', 'name': 'Quy tắc vật liệu trong suốt ở chế độ X-Ray Pin', 'condition': 'Khi kích hoạt X-Ray pin xe điện, vật liệu Mesh thân vỏ xe phải chuyển transparent = true, opacity = 0.15 và Mesh khối pin phải hiển thị nổi bật màu #FF8C00.', 'module': '3D Digital Twin', 'enforcement': 'Zustand Store dispatch action enterBatteryXrayMode() cập nhật thuộc tính Material trên Scenegraph Three.js.', 'source_file': 'worldStore.ts:enterBatteryXrayMode(), BatteryPackMesh.tsx', 'related_ucs': 'UC-3D-04'}, {'id': 'BR-3D-03', 'name': 'Quy tắc tọa độ Camera Reset', 'condition': 'Hành động reset camera phải đưa vị trí camera về chính xác tọa độ (4.5, 2.2, 4.5) và tâm ngắm LookAt về (0.0, 0.75, 0.0).', 'module': '3D Digital Twin', 'enforcement': 'Hàm resetCameraView sử dụng GSAP / TWEEN lerp mượt mà trong 800ms.', 'source_file': 'worldStore.ts:triggerCameraReset(), GarageScene.tsx', 'related_ucs': 'UC-3D-07'}, {'id': 'BR-CO-01', 'name': 'Bất biến tổng tỷ lệ sở hữu bằng đúng 100.0000%', 'condition': 'Tổng tỷ lệ phần trăm cổ phần sở hữu của toàn bộ các thành viên trong một nhóm xe phải luôn luôn bằng chính xác 100.0000% tại mọi thời điểm.', 'module': 'Co-Ownership', 'enforcement': 'Kiểm tra tổng sum(percentage) == 100.0000 trước khi commit giao dịch chuyển nhượng hoặc phân bổ cổ phần.', 'source_file': 'OwnershipTransferService.java, CoOwnershipService.java', 'related_ucs': 'UC-CO-01, UC-CO-04, UC-CO-07'}, {'id': 'BR-CO-02', 'name': 'Quy tắc giới hạn số lượng đồng sở hữu tối đa', 'condition': 'Một nhóm đồng sở hữu một phương tiện xe điện chỉ có tối thiểu 2 và tối đa 10 thành viên chính thức.', 'module': 'Co-Ownership', 'enforcement': 'Kiểm tra count(members) < 10 trước khi gửi lời mời gia nhập hoặc chấp thuận thành viên mới.', 'source_file': 'CoOwnershipService.java, MembershipInvitationService.java', 'related_ucs': 'UC-CO-01, UC-CO-02'}, {'id': 'BR-CO-03', 'name': 'Thời hạn hiệu lực của lời mời gia nhập nhóm', 'condition': 'Lời mời tham gia nhóm đồng sở hữu có thời hạn hiệu lực tối đa là 72 giờ kể từ thời điểm phát hành.', 'module': 'Co-Ownership', 'enforcement': 'Job định kỳ quét kiểm tra expires_at < now() để tự động chuyển trạng thái lời mời sang EXPIRED.', 'source_file': 'MembershipInvitationService.java:recoverPendingInvitations()', 'related_ucs': 'UC-CO-02, UC-CO-03'}, {'id': 'BR-CO-04', 'name': 'Quy tắc không nợ tồn đọng khi chuyển nhượng cổ phần', 'condition': 'Thành viên chuyển nhượng cổ phần bắt buộc phải thanh toán 100% các nghĩa vụ chi phí cá nhân tồn đọng (unpaid balance = 0).', 'module': 'Co-Ownership', 'enforcement': 'Kiểm tra ExpenseShareRepository.existsByMemberIdAndStatus(id, UNPAID) trước khi tạo yêu cầu chuyển nhượng.', 'source_file': 'OwnershipTransferService.java:createTransferRequest()', 'related_ucs': 'UC-CO-05'}, {'id': 'BR-CO-05', 'name': 'Quy tắc đồng thuận hai phía trong giao dịch chuyển dịch cổ phần', 'condition': 'Giao dịch chuyển nhượng cổ phần chỉ hoàn tất khi cả bên chuyển nhượng và bên nhận đều đã ký xác nhận điện tử đồng thuận.', 'module': 'Co-Ownership', 'enforcement': 'Chỉ chuyển trạng thái giao dịch sang COMPLETED khi transferor_consented = true và transferee_accepted = true.', 'source_file': 'OwnershipTransferController.java:confirmTransferorConsent()', 'related_ucs': 'UC-CO-06, UC-CO-07'}, {'id': 'BR-CO-06', 'name': 'Quy tắc phiên bản hóa phụ lục hợp đồng', 'condition': 'Mỗi khi có sự thay đổi tỷ lệ cổ phần hoặc thành viên trong nhóm, hệ thống phải tự động đóng phiên bản hợp đồng cũ và sinh phiên bản mới với version = old_version + 1.', 'module': 'Co-Ownership', 'enforcement': 'CoOwnershipContractService tự động tạo bản ghi mới trong co_ownership_contract_versions.', 'source_file': 'CoOwnershipContractService.java:activateContractVersion()', 'related_ucs': 'UC-CO-07'}, {'id': 'BR-BOOK-01', 'name': 'Quy tắc chống chồng lấn thời gian đặt xe (No Booking Overlap)', 'condition': 'Khoảng thời gian [startTime, endTime] của một phiên đặt xe mới không được phép giao thoa với bất kỳ phiên đặt xe nào khác (StartA < EndB và EndA > StartB).', 'module': 'Smart Booking', 'enforcement': 'Truy vấn CSDL với điều kiện khóa bi-directional overlap trước khi lưu bản ghi Booking mới.', 'source_file': 'BookingService.java:checkOverlap(), BookingRepository.java', 'related_ucs': 'UC-BOOK-01, UC-BOOK-02'}, {'id': 'BR-BOOK-02', 'name': 'Quy tắc thời gian đệm làm sạch và kiểm định (Buffer Time)', 'condition': 'Giữa hai phiên đặt xe liên tiếp của cùng một phương tiện bắt buộc phải có khoảng đệm tối thiểu 30 phút để kiểm tra và nạp sạc.', 'module': 'Smart Booking', 'enforcement': 'Hệ thống tự động cộng thêm 30 phút vào mốc kết thúc khi kiểm tra tính khả dụng của lịch đặt tiếp theo.', 'source_file': 'BookingService.java', 'related_ucs': 'UC-BOOK-02'}, {'id': 'BR-BOOK-03', 'name': 'Quy tắc khóa lịch khi xe đang bảo dưỡng (Maintenance Lock)', 'condition': 'Không cho phép đặt xe trong khoảng thời gian xe được xếp lịch bảo dưỡng (status = MAINTENANCE) hoặc đang sửa chữa.', 'module': 'Smart Booking', 'enforcement': 'Kiểm tra xung đột với bảng maintenances trước khi phê duyệt lịch đặt.', 'source_file': 'BookingService.java:110', 'related_ucs': 'UC-BOOK-02, UC-STF-02'}, {'id': 'BR-BOOK-04', 'name': 'Quy tắc hủy lịch đặt xe miễn phí', 'condition': 'Người dùng được hủy lịch đặt xe miễn phí nếu thực hiện trước giờ khởi hành tối thiểu 60 phút; nếu hủy sát giờ sẽ bị trừ điểm tín nhiệm.', 'module': 'Smart Booking', 'enforcement': 'So sánh startTime - now() >= 60 phút tại tầng Service xử lý hủy lịch.', 'source_file': 'BookingController.java:cancelBooking(), BookingService.java', 'related_ucs': 'UC-BOOK-05'}, {'id': 'BR-BOOK-05', 'name': 'Quy tắc hạn ngạch thời gian đặt xe theo tỷ lệ cổ phần', 'condition': 'Số giờ đặt xe trong tháng của mỗi thành viên được phân bổ tỷ lệ thuận với % cổ phần nắm giữ nhân với tổng giờ khả dụng (720 giờ/tháng).', 'module': 'Smart Booking', 'enforcement': 'Kiểm tra tổng số giờ đã đặt trong tháng không vượt quá quota = 720 * (ownershipPercentage / 100).', 'source_file': 'BookingService.java:validateQuota()', 'related_ucs': 'UC-BOOK-02'}, {'id': 'BR-CHG-01', 'name': 'Hệ số tổn hao hiệu suất sạc năng lượng 92%', 'condition': 'Lượng điện năng thực tế nạp vào pin xe chỉ đạt 92% điện năng xuất ra từ trụ sạc do tổn hao nhiệt và chuyển đổi AC/DC (nạp = xuất * 0.92).', 'module': 'Charging Management', 'enforcement': 'VehicleEnergyInventoryService áp dụng công thức energyAdded = rawEnergy * 0.92 trước khi cộng vào kho pin xe.', 'source_file': 'VehicleEnergyInventoryService.java:completeChargingSession()', 'related_ucs': 'UC-CHG-01, UC-CHG-03'}, {'id': 'BR-CHG-02', 'name': 'Đơn giá điện năng trạm sạc EVN', 'condition': 'Đơn giá điện cơ sở áp dụng cho phiên sạc trạm EVShare là 3.850 đ/kWh (chưa bao gồm VAT).', 'module': 'Charging Management', 'enforcement': 'Hằng số TARIFF_PRICE_PER_KWH = 3850.0 được cấu hình tại EnergyPricingConfig.', 'source_file': 'EnergyPricingConfig.java, VehicleEnergyInventoryService.java', 'related_ucs': 'UC-CHG-03'}, {'id': 'BR-CHG-03', 'name': 'Công thức giá vốn bình quân gia quyền kho năng lượng (WAC)', 'condition': 'Mỗi khi nạp thêm điện vào xe, đơn giá vốn mới WAC = (Năng lượng cũ * WAC cũ + Năng lượng nạp mới * Giá nạp mới) / Tổng năng lượng sau nạp.', 'module': 'Charging Management', 'enforcement': 'VehicleEnergyInventoryService tính toán và cập nhật giá trị WAC vào bảng vehicle_energy_inventories.', 'source_file': 'VehicleEnergyInventoryService.java:recalculateWAC()', 'related_ucs': 'UC-CHG-04'}, {'id': 'BR-CHG-04', 'name': 'Quy tắc sạc vận hành chuyên trách không gán nợ', 'condition': 'Khi nhân viên vận hành (ROLE_STAFF) thực hiện phiên sạc phục vụ công tác kỹ thuật, chi phí phiên sạc không được tính vào nợ cá nhân của nhân viên.', 'module': 'Charging Management', 'enforcement': 'Kiểm tra isOperational = true thì hạch toán chi phí vào tài khoản chung của phương tiện thay vì tài khoản cá nhân.', 'source_file': 'VehicleEnergyInventoryService.java:181', 'related_ucs': 'UC-CHG-05'}, {'id': 'BR-TRIP-01', 'name': 'Chốt chặn an toàn mức pin tối thiểu khi khởi hành (Pin >= 20%)', 'condition': 'Hệ thống nghiêm cấm bắt đầu chuyến đi (Start Trip) nếu mức dung lượng pin của xe hiện thời dưới 20% (SOC < 20%).', 'module': 'Trip Execution', 'enforcement': 'TripService ném ngoại lệ InsufficientBatteryException (HTTP 400) nếu currentSOC < 20.0.', 'source_file': 'TripService.java:startTrip()', 'related_ucs': 'UC-TRIP-01'}, {'id': 'BR-TRIP-02', 'name': 'Quy tắc bắt buộc hoàn thành biên bản bàn giao trước chuyến đi', 'condition': 'Không thể bắt đầu chuyến đi nếu biên bản bàn giao xe kỹ thuật số (VehicleHandover) chưa được nhân viên và người nhận xe ký duyệt.', 'module': 'Trip Execution', 'enforcement': 'Kiểm tra handover.status == COMPLETED trước khi cho phép chuyển trạng thái chuyến đi sang IN_PROGRESS.', 'source_file': 'TripService.java:verifyHandover()', 'related_ucs': 'UC-TRIP-01, UC-BOOK-07'}, {'id': 'BR-TRIP-03', 'name': 'Tính chi phí điện năng tiêu thụ chuyến đi theo giá WAC', 'condition': 'Chi phí năng lượng chuyến đi phải thanh toán = (Start SOC - End SOC) * Dung lượng pin danh định * Đơn giá WAC tại thời điểm kết thúc chuyến.', 'module': 'Trip Execution', 'enforcement': 'VehicleEnergyModelService tính toán số tiền và tự động tạo khoản nợ ExpenseShare cho người lái.', 'source_file': 'VehicleEnergyModelService.java, TripService.java:completeTrip()', 'related_ucs': 'UC-TRIP-05'}, {'id': 'BR-TRIP-04', 'name': 'Quy tắc xử lý phát sinh tổn hại thân vỏ mới', 'condition': 'Nếu biên bản trả xe ghi nhận tổn hại mới không có trong biên bản bàn giao ban đầu, chi phí khắc phục được gán 100% trách nhiệm cho người vừa kết thúc chuyến đi.', 'module': 'Trip Execution', 'enforcement': 'DamageRecordService gắn responsible_user_id = trip.driver_id và kích hoạt quy trình bồi hoàn.', 'source_file': 'DamageController.java:recordTripDamage()', 'related_ucs': 'UC-TRIP-06, UC-DISP-01'}, {'id': 'BR-EXP-01', 'name': 'Quy tắc làm tròn tài chính phần dư lớn nhất Hare-Niemeyer', 'condition': 'Khi phân bổ chi phí hóa đơn cho các thành viên, tổng số tiền phân bổ sau làm tròn tới hàng đơn vị đồng VND phải bằng chính xác 100% số tiền trên hóa đơn gốc, không được chênh lệch dù chỉ 1 đồng.', 'module': 'Expense Sharing', 'enforcement': 'ExpenseShareService thực thi thuật toán Hare-Niemeyer (Largest Remainder Method) để bù trừ phần dư phần trăm.', 'source_file': 'ExpenseShareService.java:228', 'related_ucs': 'UC-EXP-01, UC-EXP-02'}, {'id': 'BR-EXP-02', 'name': 'Ngăn chặn tự phê duyệt thanh toán nợ của chính mình (No Self-Approval)', 'condition': 'Người dùng không được phép tự phê duyệt (Verify/Approve) giao dịch thanh toán nợ cá nhân của chính tài khoản mình.', 'module': 'Expense Sharing', 'enforcement': 'Kiểm tra payment.user_id != currentPrincipal.id; ném lỗi ForbiddenException nếu trùng lặp.', 'source_file': 'PersonalPaymentService.java:verifyPayment()', 'related_ucs': 'UC-EXP-06'}, {'id': 'BR-EXP-03', 'name': 'Quy tắc bắt buộc đính kèm ảnh chứng từ hóa đơn', 'condition': 'Mọi khoản chi phí chung phát sinh trên 200.000 đ đều bắt buộc phải đính kèm tối thiểu 1 ảnh chụp chứng từ hoặc hóa đơn GTGT hợp lệ.', 'module': 'Expense Sharing', 'enforcement': 'Kiểm tra receipt_image_url != null trước khi chuyển trạng thái chi phí sang PENDING_APPROVAL.', 'source_file': 'ExpenseService.java:recordExpense()', 'related_ucs': 'UC-EXP-01'}, {'id': 'BR-EXP-04', 'name': 'Thời hạn thanh toán nghĩa vụ chi phí định kỳ', 'condition': 'Các thành viên có nghĩa vụ thanh toán đầy đủ các khoản chi phí phân bổ trong vòng tối đa 7 ngày kể từ ngày chốt sao kê hàng tháng.', 'module': 'Expense Sharing', 'enforcement': 'Sau 7 ngày, hệ thống tự động khóa quyền đặt xe của thành viên nếu tổng nợ quá hạn > 500.000 đ.', 'source_file': 'ExpenseShareService.java:checkOverdueBalances()', 'related_ucs': 'UC-EXP-05, UC-BOOK-02'}, {'id': 'BR-EXP-05', 'name': 'Quy tắc phòng chống trùng lặp và tính bất biến phân bổ chi phí (Duplicate Expense Prevention & Allocation Idempotency)', 'condition': 'Một khoản chi phí chỉ được sinh nghĩa vụ phân bổ (ExpenseShare) khi đã ở trạng thái APPROVED. Thao tác phân bổ chi phí là lũy đẳng (idempotent): không được phép tạo trùng lặp ExpenseShare cho cùng một expense_id. Chi phí năng lượng từ một chuyến đi chỉ được kết xuất hóa đơn một lần duy nhất, gán trực tiếp 100% trách nhiệm cho người lái (USER_RESPONSIBILITY). Các bản ghi quỹ chung cũ chỉ lưu trữ dưới dạng hồ sơ lịch sử tham chiếu.', 'module': 'Expense Sharing', 'enforcement': 'Kiểm tra expense.status == APPROVED, kiểm tra expenseShareRepository.existsByExpenseId(expense.getId()), và expenseRepository.findByRelatedTripId(trip.getId())', 'source_file': 'backend/src/main/java/com/evshare/expense/service/ExpenseShareService.java', 'related_ucs': 'UC-FIN-01, UC-FIN-03'}, {'id': 'BR-VOTE-01', 'name': 'Nguyên tắc biểu quyết theo trọng số cổ phần (Weighted Voting)', 'condition': 'Trọng số phiếu biểu quyết của mỗi thành viên bằng đúng tỷ lệ % cổ phần sở hữu xe của thành viên đó tại thời điểm mở đề xuất.', 'module': 'Democratic Voting', 'enforcement': 'ProposalVote.voteWeight = OwnershipShare.percentage; tổng điểm biểu quyết bằng tổng trọng số các phiếu.', 'source_file': 'VoteProposalService.java:castVote()', 'related_ucs': 'UC-VOTE-01, UC-VOTE-02'}, {'id': 'BR-VOTE-02', 'name': 'Ngưỡng quá bán thông qua đề xuất (Voting Quorum)', 'condition': "Một đề xuất biểu quyết chỉ được coi là thông qua (PASSED) khi tổng trọng số phiếu 'Đồng ý' đạt trên 50.0000% tổng cổ phần nhóm (hoặc 66.0000% đối với các quyết định sửa chữa lớn).", 'module': 'Democratic Voting', 'enforcement': 'VoteProposalService so sánh yesWeight / totalWeight với threshold trước khi cập nhật trạng thái đề xuất.', 'source_file': 'VoteProposalService.java:finalizeProposal()', 'related_ucs': 'UC-VOTE-05'}, {'id': 'BR-VOTE-03', 'name': 'Quy tắc bắt buộc biểu quyết khi chi phí bảo dưỡng lớn', 'condition': 'Mọi lệnh bảo dưỡng hoặc sửa chữa có tổng dự toán chi phí vượt quá 5.000.000 đ bắt buộc phải tạo đề xuất biểu quyết và được nhóm thông qua trước khi nhân viên bắt đầu thi công.', 'module': 'Democratic Voting', 'enforcement': 'MaintenanceService tự động kích hoạt tạo VoteProposal nếu estimatedCost > 5000000 đ.', 'source_file': 'MaintenanceService.java:createMaintenance()', 'related_ucs': 'UC-VOTE-03, UC-STF-02'}, {'id': 'BR-VOTE-04', 'name': 'Thời hạn biểu quyết đề xuất nhóm', 'condition': 'Thời gian mở biểu quyết của một đề xuất kéo dài tối thiểu 24 giờ và tối đa 72 giờ kể từ thời điểm khởi tạo.', 'module': 'Democratic Voting', 'enforcement': 'Job định kỳ kiểm tra current_time >= voting_deadline để tự động chốt kết quả biểu quyết.', 'source_file': 'VoteProposalService.java:autoFinalizeExpiredProposals()', 'related_ucs': 'UC-VOTE-01, UC-VOTE-05'}, {'id': 'BR-VOTE-05', 'name': 'Nguyên tắc bất biến của phiếu bầu đã phát hành', 'condition': 'Thành viên sau khi đã xác nhận bỏ phiếu biểu quyết thì không được phép thay đổi ý kiến hoặc hủy bỏ phiếu bầu của mình.', 'module': 'Democratic Voting', 'enforcement': 'ProposalVoteRepository.existsByProposalIdAndVoterId(propId, userId) chặn hành vi gửi vote lần hai.', 'source_file': 'VoteProposalController.java:castVote()', 'related_ucs': 'UC-VOTE-02'}, {'id': 'BR-DISP-01', 'name': 'Quy tắc tính phí phạt trễ giờ trả xe xâm lấn', 'condition': 'Người dùng trả xe muộn vượt quá 15 phút mà không gia hạn hợp lệ sẽ bị tính mức phạt 100.000 đ cho mỗi 30 phút trễ, số tiền phạt được đền bù trực tiếp cho người bị ảnh hưởng kế tiếp.', 'module': 'Dispute Resolution', 'enforcement': 'BookingIncidentDetectionService tự động tính toán số tiền phạt trong prefilled dispute.', 'source_file': 'BookingIncidentDetectionService.java:detectConflicts()', 'related_ucs': 'UC-DISP-02'}, {'id': 'BR-DISP-02', 'name': 'Quy tắc tính khách quan của hòa giải viên (Independent Mediator)', 'condition': 'Nhân viên được phân công làm hòa giải viên không được là thành viên trong nhóm đồng sở hữu của chiếc xe đang xảy ra tranh chấp.', 'module': 'Dispute Resolution', 'enforcement': 'Kiểm tra !CoOwnershipMemberRepository.existsByGroupIdAndUserId(group.id, staff.id).', 'source_file': 'DisputeService.java:assignStaffMediator()', 'related_ucs': 'UC-DISP-03'}, {'id': 'BR-DISP-03', 'name': 'Thời hạn giải quyết khiếu nại tranh chấp', 'condition': 'Hồ sơ khiếu nại tranh chấp phải được tiếp nhận và xử lý hòa giải trong thời hạn tối đa 5 ngày làm việc kể từ thời điểm mở hồ sơ.', 'module': 'Dispute Resolution', 'enforcement': 'Hệ thống phát tín hiệu cảnh báo màu đỏ trên Staff Dashboard nếu dispute quá hạn 5 ngày chưa có kết luận.', 'source_file': 'DisputeService.java', 'related_ucs': 'UC-DISP-01, UC-DISP-06'}, {'id': 'BR-DISP-04', 'name': 'Quy tắc tự động gạch nợ sau khi hòa giải bồi thường được xác nhận', 'condition': 'Khoản bồi thường tranh chấp chỉ được ghi nhận hoàn tất khi có chứng từ chuyển tiền hợp lệ và được hòa giải viên xác nhận phê duyệt.', 'module': 'Dispute Resolution', 'enforcement': 'DisputeCompensationPayment chuyển trạng thái sang VERIFIED, tự động trừ nghĩa vụ tài chính liên quan.', 'source_file': 'DisputeService.java:approveCompensationEvidence()', 'related_ucs': 'UC-DISP-05, UC-DISP-06'}, {'id': 'BR-SEC-01', 'name': 'Bảo vệ thông tin cá nhân: Không để lộ thông tin mật', 'condition': 'Tuyệt đối không để lộ mật khẩu, mã hash BCrypt hoặc mã bí mật trong bất kỳ DTO phản hồi API nào ra môi trường bên ngoài.', 'module': 'Security', 'enforcement': 'Sử dụng annotation @JsonIgnore trên trường passwordHash tại User.java và mapping sang UserResponse không chứa trường mật khẩu.', 'source_file': 'User.java, UserResponse.java', 'related_ucs': 'UC-AUTH-01, UC-AUTH-05'}, {'id': 'BR-SEC-02', 'name': 'Bắt buộc ghi nhật ký kiểm toán cho các hành vi thay đổi trạng thái nhạy cảm', 'condition': 'Mọi thao tác thay đổi số dư cổ phần, duyệt thanh toán chi phí, khóa tài khoản và thay đổi cấu hình xe bắt buộc phải phát sinh bản ghi AuditLog lưu CSDL.', 'module': 'Security', 'enforcement': 'AuditLogService được gọi đồng bộ hoặc bất đồng bộ (@Async) trong các phương thức Service nhạy cảm.', 'source_file': 'AuditLogService.java, AdminController.java', 'related_ucs': 'UC-CO-07, UC-EXP-06, UC-ADM-02'}, {'id': 'BR-SEC-03', 'name': 'Quy tắc phân vùng thẩm quyền đa cấp (Cross-Role Authorization Guard)', 'condition': 'Người dùng thuộc vai trò CO_OWNER tuyệt đối không được phép gọi các API thuộc phân quyền STAFF hoặc ADMIN và ngược lại.', 'module': 'Security', 'enforcement': "Spring Security Method Security với @PreAuthorize('hasRole(...)') được áp dụng chặt chẽ trên toàn bộ 27 Controller.", 'source_file': 'SecurityConfig.java, all Controller classes', 'related_ucs': 'All Use Cases'}]

ROLE_PERMISSION_MATRIX = [{'module': '1. Xác thực & Tài khoản (Auth)', 'admin': 'Quản lý toàn bộ tài khoản, đổi role, khóa/mở khóa', 'staff': 'Đổi mật khẩu cá nhân, cập nhật hồ sơ trực ban', 'co_owner': 'Đăng ký, đăng nhập, đổi mật khẩu, xem hồ sơ cá nhân', 'ownership_cond': 'Người dùng chỉ được sửa thông tin cá nhân của chính mình', 'restrictions': 'Không thể tự cấp quyền ADMIN cho bản thân', 'source_evidence': 'AuthController.java, SecurityConfig.java'}, {'module': '2. Tương tác 3D Digital Twin', 'admin': 'Xem toàn bộ mô hình 3D xe trong hệ thống, cấu hình tọa độ', 'staff': 'Xem mô hình 3D, kiểm tra điểm hư hại của xe trực ban', 'co_owner': 'Xem 3D xe thuộc nhóm sở hữu, tương tác X-Ray, Hotspots', 'ownership_cond': 'Chỉ xem đầy đủ dữ liệu telemetry của xe thuộc nhóm sở hữu', 'restrictions': 'Không thể xem thông tin mật của xe ngoài nhóm', 'source_evidence': 'GarageScene.tsx, VehicleDigitalTwin.tsx'}, {'module': '3. Nhóm Đồng sở hữu (Co-Ownership)', 'admin': 'Xem và quản trị toàn bộ các nhóm sở hữu trong hệ thống', 'staff': 'Xem danh sách xe và thành viên để phối hợp bàn giao', 'co_owner': 'Tạo nhóm, mời thành viên, chuyển nhượng cổ phần trong nhóm', 'ownership_cond': 'Phải là thành viên hợp lệ của nhóm xe tương ứng', 'restrictions': 'Tổng cổ phần luôn phải bảo toàn đúng 100.0000%', 'source_evidence': "CoOwnershipController.java:hasAnyRole('CO_OWNER')"}, {'module': '4. Lịch đặt xe (Smart Booking)', 'admin': 'Xem toàn bộ lịch đặt xe, hủy lịch khi có sự cố khẩn cấp', 'staff': 'Xem lịch đặt để chuẩn bị bàn giao và đón xe hoàn trả', 'co_owner': 'Đặt xe, gia hạn phiên dùng, hủy lịch trước 60 phút', 'ownership_cond': 'Chỉ được đặt xe thuộc nhóm đồng sở hữu của mình', 'restrictions': 'Không được đặt chồng lấn lịch người khác, hạn ngạch theo % cổ phần', 'source_evidence': 'BookingController.java, BookingService.java'}, {'module': '5. Bàn giao xe (Vehicle Handover)', 'admin': 'Giám sát quy trình bàn giao, kiểm toán biên bản kỹ thuật', 'staff': 'Lập biên bản bàn giao, chụp ảnh kiểm định, ký bàn giao xe', 'co_owner': 'Kiểm tra thực tế xe, ký số xác nhận nhận xe', 'ownership_cond': 'Người nhận xe phải là người đứng tên trên lịch đặt tương ứng', 'restrictions': 'Bắt buộc có xác nhận hai phía mới được nhận xe', 'source_evidence': "VehicleHandoverController.java:hasAnyRole('STAFF', 'CO_OWNER')"}, {'module': '6. Quản lý Sạc điện (Charging)', 'admin': 'Cấu hình trạm sạc, định giá điện, xem báo cáo năng lượng', 'staff': 'Thực hiện sạc vận hành chuyên trách không gán nợ', 'co_owner': 'Cắm sạc xe, theo dõi sạc 3D, kết thúc phiên nạp điện', 'ownership_cond': 'Người dùng sạc xe thuộc nhóm hoặc xe đang trong chuyến đi', 'restrictions': 'Người lạ không được phép can thiệp dừng phiên sạc của người khác', 'source_evidence': 'ChargingSessionController.java, VehicleEnergyInventoryService.java'}, {'module': '7. Chuyến đi (Trip Execution)', 'admin': 'Xem lịch sử toàn bộ các chuyến đi, can thiệp sự cố hành trình', 'staff': 'Nghiệm thu hoàn trả xe, xác nhận kết thúc chuyến đi', 'co_owner': 'Bắt đầu chuyến đi, theo dõi tiêu hao năng lượng, yêu cầu trả xe', 'ownership_cond': 'Chỉ người có lịch đặt hợp lệ mới được bắt đầu chuyến đi', 'restrictions': 'Chặn bắt đầu chuyến đi nếu pin xe < 20%', 'source_evidence': "TripController.java:hasRole('CO_OWNER')"}, {'module': '8. Chi phí & Quỹ chung (Expense & Fund)', 'admin': 'Kiểm toán tài chính, xem báo cáo tổng hợp dòng tiền', 'staff': 'Nhập hóa đơn chi phí bảo dưỡng, đối soát chứng từ thanh toán', 'co_owner': 'Đóng quỹ chung, thanh toán nợ cá nhân, xem phân bổ chi phí', 'ownership_cond': 'Xem và thanh toán chi phí phát sinh thuộc nhóm xe của mình', 'restrictions': 'Nghiêm cấm tự phê duyệt giao dịch thanh toán nợ của chính mình', 'source_evidence': 'ExpenseController.java, PersonalPaymentService.java'}, {'module': '9. Biểu quyết dân chủ (Voting)', 'admin': 'Giám sát tính minh bạch, hủy bỏ biểu quyết vi phạm quy chế', 'staff': 'Tạo đề xuất biểu quyết tự động khi chi phí sửa chữa vượt ngưỡng', 'co_owner': 'Tạo đề xuất biểu quyết, bỏ phiếu với trọng số theo % cổ phần', 'ownership_cond': 'Chỉ thành viên nắm giữ cổ phần xe mới có quyền bỏ phiếu', 'restrictions': 'Không thể thay đổi phiếu sau khi đã gửi xác nhận', 'source_evidence': "VoteProposalController.java:hasRole('CO_OWNER')"}, {'module': '10. Giải quyết khiếu nại (Dispute)', 'admin': 'Phân công hòa giải viên, phê chuẩn quyết định bồi hoàn lớn', 'staff': 'Đóng vai trò hòa giải viên trung gian, đối soát chứng cứ', 'co_owner': 'Gửi khiếu nại, nộp bằng chứng, biểu quyết chấp thuận bồi hoàn', 'ownership_cond': 'Chỉ các bên liên quan trực tiếp mới được tham gia phiên hòa giải', 'restrictions': 'Hòa giải viên không được là thành viên trong nhóm đang tranh chấp', 'source_evidence': "DisputeController.java:hasAnyRole('STAFF', 'ADMIN')"}, {'module': '11. Quản trị hệ thống (Administration)', 'admin': 'Toàn quyền cấu hình, xem KPI Dashboard, xem Audit Log CSDL', 'staff': 'Không có quyền truy cập', 'co_owner': 'Không có quyền truy cập', 'ownership_cond': 'Yêu cầu quyền tối cao ROLE_ADMIN', 'restrictions': 'Chặn toàn bộ các request không có claim ROLE_ADMIN', 'source_evidence': 'AdminController.java:@PreAuthorize("hasRole(\'ADMIN\')")'}]

